#include <iostream>
#include <regex>
#include <string>

int main() {
  std::string filename = "myprogram.cpp";
  std::regex fileRegex("[[:alnum:]]+\.(cpp|cxx|cc)");
  std::smatch match;

  if (std::regex_match(filename, match, fileRegex)) {
    std::cout << "Matched filename: " << match[0] << std::endl;
  } else {
    std::cout << "Filename does not match the pattern." << std::endl;
  }
  return 0;
}
